package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaReducedDecimalFractionTest {
 @Test public void officialExampleRequiresReductionFromPublicStatement(){Question q=DecimalToFractionSupply.makeReduced(0,45,2);q.answers[0]="999";q.expression="999";q.kind="number";assertTrue(new Checker().check(q,List.of(),List.of("9/20")).correct());assertEquals("약분 필요",new Checker().check(q,List.of(),List.of("45/100")).message);assertFalse(new Checker().check(q,List.of(),List.of("9/21")).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());List<String> a=List.of("0.45","2","100","45","5","9","20");for(int i=0;i<7;i++)assertTrue(h.step(i).accepts(a.get(i)));}
 @Test public void zeroWholeTrailingZeroAndOldEquivalentContract(){for(int[] v:new int[][]{{0,0,2},{99,0,2},{0,70,2},{0,5,2}}){Question q=DecimalToFractionSupply.makeReduced(v[0],v[1],v[2]);Rational expected=Expression.number(DecimalToFractionSupply.read(q));assertTrue(new Checker().check(q,List.of(),List.of(expected.n+"/"+expected.d)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}Question old=DecimalToFractionSupply.make(0,45,2);assertTrue(new Checker().check(old,List.of(),List.of("45/100")).correct());assertEquals(4,HelpPlan.forQuestion(old).size());assertFalse(CurriculumLimits.NONE.reducedDecimalFraction());}
 @Test public void actualNaSixSupplyKeepsOriginalPrecisionAndReducedPrompt(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(DecimalToFractionSupply.ID,6));var l=GlobalCurriculum.limits(pack.id,DecimalToFractionSupply.ID,6);assertTrue(l.reducedDecimalFraction());Generator g=new Generator(new Random(287));List<String> recent=new ArrayList<>();Set<Integer> places=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(DecimalToFractionSupply.ID,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());String raw=DecimalToFractionSupply.read(q);assertNotNull(raw);assertTrue(q.prompt.contains("기약분수"));places.add(raw.length()-raw.indexOf('.')-1);assertTrue(l.allows(q));Rational v=Expression.number(raw);assertTrue(new Checker().check(q,List.of(),List.of(v.n+"/"+v.d)).correct());assertEquals(7,HelpPlan.forQuestion(q).size());}assertEquals(Set.of(1,2),places);}
}
